import time
from collections import deque

class RateLimiter:
    """A refined rate limiter using a deque to track timestamps of allowed requests 
    within a sliding time window, ensuring improved readability and efficiency."""

    def __init__(self, max_requests: int, window_seconds: float):
        if max_requests <= 0 or window_seconds <= 0:
            raise ValueError("max_requests and window_seconds must be positive.")
        self.max_requests = max_requests
        self.window_seconds = window_seconds
        self.requests = deque()

    def allow(self) -> bool:
        """Check if a new request is allowed within the rate limit."""
        current_time = time.time()
        self._remove_old_requests(current_time)

        if len(self.requests) < self.max_requests:
            self.requests.append(current_time)
            return True
        return False

    def _remove_old_requests(self, current_time: float):
        """Remove requests that are outside the defined time window."""
        while self.requests and self.requests[0] <= current_time - self.window_seconds:
            self.requests.popleft()
